        counts = job.result().get_counts()
        exp_val = compute_expectation(counts, graph)
        return exp_val

    res = minimize(objective, initial_params, method='COBYLA')
    opt_params = res.x

    # Run with optimized parameters
    param_binds = {}
    for p, val in zip(circuit.parameters, opt_params):
        param_binds[p] = [float(val)]
    job = aer_sim.run(circuit, parameter_binds=param_binds)
    counts = job.result().get_counts()

    # Top two most frequent solutions
    sorted_counts = sorted(counts.items(), key=lambda x: x[1], reverse=True)
    top_two = [x[0] for x in sorted_counts[:2]]
    return top_two
